# IPTVPremium: SOMENTE Home: PNGs branco/cinza por tema e zoom de foco nos utilitarios. Base: java.zip atual. Windows PowerShell 5.1 / PowerShell 7.
[CmdletBinding()]
param([string]$Projeto = (Get-Location).Path)
Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'
function Get-BytesHash([byte[]]$Bytes) {
    $sha = [Security.Cryptography.SHA256]::Create()
    try { return ([BitConverter]::ToString($sha.ComputeHash($Bytes))).Replace('-', '') }
    finally { $sha.Dispose() }
}
function Get-TextHash([byte[]]$Bytes) {
    $text = [Text.Encoding]::UTF8.GetString($Bytes).TrimStart([char]0xFEFF).Replace("`r`n", "`n")
    return Get-BytesHash ([Text.Encoding]::UTF8.GetBytes($text))
}
$files = @(
    @{ Path = 'app/src/main/java/br/com/flaviotorres/iptvpremium/ui/home/MarbleHomePngAssets.kt'; Binary = $false; Allowed = @('3D670E679CB0A81D7010835FC856F62297A73AD45504B8E8AF99C0C3E62846DC'); MayCreate = $false; After = '4DA24420613CF04533F66698C3DE7818764C51A7D0F352042926662139E63D6C'; PayloadHash = '4DA24420613CF04533F66698C3DE7818764C51A7D0F352042926662139E63D6C'; Data = '' },
    @{ Path = 'app/src/main/java/br/com/flaviotorres/iptvpremium/ui/home/MarbleLayeredHomeArtwork.kt'; Binary = $false; Allowed = @('34110E4710F1EED3F81AEA7D9B3F15811D3D8E60DD975DA9DBF4F069CD5A5751'); MayCreate = $false; After = 'FA47444BE5E586C255D1728587AE5AF06FBD655136E280FA86739B35105ACAAA'; PayloadHash = 'FA47444BE5E586C255D1728587AE5AF06FBD655136E280FA86739B35105ACAAA'; Data = '' },
    @{ Path = 'app/src/main/java/br/com/flaviotorres/iptvpremium/ui/home/MarbledHomeScreen.kt'; Binary = $false; Allowed = @('84AADFA3981A33E5D41734B27B76F77AC3079B295A75F8FA2379200E2AF85113'); MayCreate = $false; After = '3D23038D6495293E691F210D90A82FB0738DB90A78A570DB315DC41968496D59'; PayloadHash = '3D23038D6495293E691F210D90A82FB0738DB90A78A570DB315DC41968496D59'; Data = '' },
    @{ Path = 'app/src/main/res/drawable-nodpi/home_original_blue_gray.png'; Binary = $true; Allowed = @(); MayCreate = $true; After = 'E5CEC3B865469D7C8FBCF9C7B46C0C8223FB7F662167ED996C69C5D323F018A4'; PayloadHash = 'E5CEC3B865469D7C8FBCF9C7B46C0C8223FB7F662167ED996C69C5D323F018A4'; Data = '' },
    @{ Path = 'app/src/main/res/drawable-nodpi/home_original_blue_white.png'; Binary = $true; Allowed = @(); MayCreate = $true; After = '4E94C8D5C7AC86FB58E48BDDA30D5CDBCAF345CBD3D29E8584E67A31C766CEA5'; PayloadHash = '4E94C8D5C7AC86FB58E48BDDA30D5CDBCAF345CBD3D29E8584E67A31C766CEA5'; Data = '' },
    @{ Path = 'app/src/main/res/drawable-nodpi/home_original_gold_gray.png'; Binary = $true; Allowed = @(); MayCreate = $true; After = 'F60901B9F58C64C43055D92BD9E0E029D7DA74781668E1C607FEDB01B7E9D223'; PayloadHash = 'F60901B9F58C64C43055D92BD9E0E029D7DA74781668E1C607FEDB01B7E9D223'; Data = '' },
    @{ Path = 'app/src/main/res/drawable-nodpi/home_original_gold_white.png'; Binary = $true; Allowed = @(); MayCreate = $true; After = 'AB30536819A83558B772421275D33BA8301DAB83D8A503D8F2773A17B2B99F3F'; PayloadHash = 'AB30536819A83558B772421275D33BA8301DAB83D8A503D8F2773A17B2B99F3F'; Data = '' },
    @{ Path = 'app/src/main/res/drawable-nodpi/home_original_pink_gray.png'; Binary = $true; Allowed = @(); MayCreate = $true; After = 'F2BC70CBC2907BA13085EF6DD2EBFECE1AD18D9799E0417FE6B1A6BD2247B4A9'; PayloadHash = 'F2BC70CBC2907BA13085EF6DD2EBFECE1AD18D9799E0417FE6B1A6BD2247B4A9'; Data = '' },
    @{ Path = 'app/src/main/res/drawable-nodpi/home_original_pink_white.png'; Binary = $true; Allowed = @(); MayCreate = $true; After = '9877F2A236189218EA72C90317DAC1E871662CEC96BE7B4936FD72A006CB8F78'; PayloadHash = '9877F2A236189218EA72C90317DAC1E871662CEC96BE7B4936FD72A006CB8F78'; Data = '' },
    @{ Path = 'app/src/main/res/drawable-nodpi/home_original_purple_gray.png'; Binary = $true; Allowed = @(); MayCreate = $true; After = 'EB04E6BE7963D375E600605329ED52FC6C49F5F1C13E1B87B24216620E52F94E'; PayloadHash = 'EB04E6BE7963D375E600605329ED52FC6C49F5F1C13E1B87B24216620E52F94E'; Data = '' },
    @{ Path = 'app/src/main/res/drawable-nodpi/home_original_purple_white.png'; Binary = $true; Allowed = @(); MayCreate = $true; After = '064967B7D702FC8EE25B0201D298326DD21EA378981B8C05D37D3EB282DB3F44'; PayloadHash = '064967B7D702FC8EE25B0201D298326DD21EA378981B8C05D37D3EB282DB3F44'; Data = '' },
    @{ Path = 'app/src/main/res/drawable-nodpi/home_original_red_gray.png'; Binary = $true; Allowed = @(); MayCreate = $true; After = 'E3C90CB895851CB648D1FB8601A5857F1006764347B68859712F19359293BE94'; PayloadHash = 'E3C90CB895851CB648D1FB8601A5857F1006764347B68859712F19359293BE94'; Data = '' },
    @{ Path = 'app/src/main/res/drawable-nodpi/home_original_red_white.png'; Binary = $true; Allowed = @(); MayCreate = $true; After = '4202F9FDCC3AFCA56D1ADBB2AEBC69882AAB4133D31F295EBB1543AAFAC42BF6'; PayloadHash = '4202F9FDCC3AFCA56D1ADBB2AEBC69882AAB4133D31F295EBB1543AAFAC42BF6'; Data = '' }
)
$root = (Resolve-Path -LiteralPath $Projeto).Path
if (!(Test-Path -LiteralPath (Join-Path $root 'app/build.gradle.kts'))) {
    throw 'Abra o terminal na raiz de IPTVPremium (pasta com app e gradlew), ou informe -Projeto.'
}
# Verifica a versao de todos os arquivos antes de escrever qualquer mudanca.
$pending = @()
foreach ($file in $files) {
    $path = Join-Path $root $file.Path
    $present = Test-Path -LiteralPath $path -PathType Leaf
    $original = $null
    if ($present) {
        $original = [IO.File]::ReadAllBytes($path)
        $current = if ($file.Binary) { Get-BytesHash $original } else { Get-TextHash $original }
        if ($current -eq $file.After) { continue }
        if ($file.Allowed -notcontains $current) {
            throw "Arquivo com mudancas diferentes da versao enviada: $($file.Path). Nada foi alterado; suas mudancas foram preservadas."
        }
    } elseif (!$file.MayCreate) {
        throw "Arquivo necessario ausente: $($file.Path). Nada foi alterado."
    }
    $packed = [IO.MemoryStream]::new([Convert]::FromBase64String($file.Data))
    $gzip = [IO.Compression.GZipStream]::new($packed, [IO.Compression.CompressionMode]::Decompress)
    $plain = [IO.MemoryStream]::new()
    try { $gzip.CopyTo($plain); $bytes = $plain.ToArray() }
    finally { $gzip.Dispose(); $plain.Dispose(); $packed.Dispose() }
    if ((Get-BytesHash $bytes) -ne $file.PayloadHash) { throw 'Pacote com integridade invalida. Nada foi alterado.' }
    $pending += @{ Path = $path; Relative = $file.Path; Bytes = $bytes; Original = $original; Present = $present; Hash = $file.PayloadHash }
}
if ($pending.Count -eq 0) {
    Write-Host 'Esta atualizacao ja esta aplicada.' -ForegroundColor Green
    return
}
$backup = Join-Path $root ('.navigation-backups/home-branco-cinza-' + (Get-Date -Format 'yyyyMMdd-HHmmss') + '-' + [guid]::NewGuid().ToString('N').Substring(0,8))
[IO.Directory]::CreateDirectory($backup) | Out-Null
foreach ($file in $pending) {
    if ($file.Present) {
        $copy = Join-Path $backup $file.Relative
        [IO.Directory]::CreateDirectory([IO.Path]::GetDirectoryName($copy)) | Out-Null
        [IO.File]::Copy($file.Path, $copy, $false)
        if ((Get-FileHash -LiteralPath $copy -Algorithm SHA256).Hash -ne (Get-BytesHash $file.Original)) {
            throw 'Backup nao passou na verificacao. Nenhum arquivo do projeto foi alterado.'
        }
    }
}
@($pending | ForEach-Object { @{ path = $_.Relative; existed = $_.Present } }) |
    ConvertTo-Json | Set-Content -LiteralPath (Join-Path $backup 'manifest.json') -Encoding UTF8
try {
    foreach ($file in $pending) {
        [IO.Directory]::CreateDirectory([IO.Path]::GetDirectoryName($file.Path)) | Out-Null
        [IO.File]::WriteAllBytes($file.Path, $file.Bytes)
        if ((Get-FileHash -LiteralPath $file.Path -Algorithm SHA256).Hash -ne $file.Hash) { throw "Falha ao gravar $($file.Relative)." }
    }
} catch {
    foreach ($file in $pending) {
        if ($file.Present) { [IO.File]::WriteAllBytes($file.Path, $file.Original) }
        elseif (Test-Path -LiteralPath $file.Path -PathType Leaf) { [IO.File]::Delete($file.Path) }
    }
    throw
}
Write-Host 'Atualizacao aplicada: icones branco/cinza nos 5 temas; Atualizar e Configuracoes aumentam sem mudar de cor.' -ForegroundColor Green
Write-Host "Backup: $backup"
Write-Host 'Compile e execute pelo Android Studio para validar no seu aparelho.'
